const allCandidates = [];

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31 + str.charCodeAt(i)) | 0;
  }
  return hash.toString(36);
}

for (const item of $input.all()) {
  const html = item.json.data;
  if (!html) continue;

  const regex = /<div class="text">([\s\S]*?)<\/div>/g;
  let match;

  while ((match = regex.exec(html)) !== null) {
    let text = match[1]
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<[^>]*>/g, '');

    text = text
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&laquo;/g, '«')
      .replace(/&raquo;/g, '»');

    text = text.replace(/[ \t]+/g, ' ').replace(/\n{2,}/g, '\n').trim();

    const wordCount = text.split(/\s+/).filter(Boolean).length;
    if (wordCount >= 50 && wordCount <= 100) {
      allCandidates.push({ jokeText: text, wordCount, hash: simpleHash(text) });
    }
  }
}

const seen = new Set();
const candidates = allCandidates.filter(c => {
  if (seen.has(c.hash)) return false;
  seen.add(c.hash);
  return true;
});

return [{ json: { candidates } }]; // candidates может быть пустым массивом — это нормально, дальше решает Try Pick Joke

const jokeText = $('Try Pick Joke').first().json.jokeText;
const inputItem = $('Convert to File').first();

function escapeHtml(text) {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

let body = escapeHtml(jokeText);
let caption = `😂 <b>Анекдот дня про Вовочку</b>\n\n${body}\n\n<i>Источник: anekdot.ru</i>`;

// у Telegram лимит подписи к фото — 1024 символа
if (caption.length > 1024) {
  const overhead = caption.length - body.length;
  const maxBodyLength = 1024 - overhead - 3;
  body = body.slice(0, maxBodyLength) + '...';
  caption = `😂 <b>Анекдот дня про Вовочку</b>\n\n${body}`;
}

return [{
  json: { caption },
  binary: inputItem.binary
}];

const input = $input.first().json;
const page = parseInt(input.current_page ?? input.nextPage, 10) || 1;
const rowId = input.row_id ?? input.rowId;
const attempt = parseInt(input.attempt, 10) || 0;
const imagesFolderId = input.images_folder_id ?? input.imagesFolderId;
const documentId = input.document_id ?? input.documentId;
const tag = 'вовочка';
const url = page === 1
  ? `https://www.anekdot.ru/tags/${encodeURIComponent(tag)}/?sort=sum`
  : `https://www.anekdot.ru/tags/${encodeURIComponent(tag)}/${page}?sort=sum`;

return [{ json: { url, page, rowId, attempt, imagesFolderId, documentId } }];

const MAX_ATTEMPTS = 15;

const candidates = $('Find Joke').first().json.candidates;
const usedHashes = $input.all().map(item => item.json.hash).filter(Boolean);
const currentPage = $('Build Page URL').first().json.page;
const rowId = $('Build Page URL').first().json.rowId;
const attempt = $('Build Page URL').first().json.attempt || 0;

const chosen = candidates.find(c => !usedHashes.includes(c.hash));

if (chosen) {
  return [{ json: { found: true, ...chosen, foundPage: currentPage, row_id: rowId } }];
}

if (attempt + 1 >= MAX_ATTEMPTS) {
  throw new Error(`Перебрали ${MAX_ATTEMPTS} страниц подряд и не нашли ни одного неиспользованного анекдота. Похоже, тег исчерпан целиком — нужно вмешательство вручную (сменить тег/источник или почистить UsedJokes).`);
}

const imagesFolderId = $('Build Page URL').last().json.imagesFolderId;
const documentId = $('Build Page URL').last().json.documentId;

return [{ json: { found: false, nextPage: currentPage + 1, row_id: rowId, attempt: attempt + 1, imagesFolderId, documentId } }];

const MAX_ATTEMPTS = 15;

const currentPage = $('Build Page URL').last().json.page;
const rowId = $('Build Page URL').last().json.rowId;
const attempt = $('Build Page URL').last().json.attempt || 0;
const imagesFolderId = $('Build Page URL').last().json.imagesFolderId;
const documentId = $('Build Page URL').last().json.documentId;

if (attempt + 1 >= MAX_ATTEMPTS) {
  throw new Error(`Перебрали ${MAX_ATTEMPTS} страниц подряд — на них вообще не нашлось анекдотов нужной длины. Похоже, тег исчерпан целиком — нужно вмешательство вручную (сменить тег/источник).`);
}

return [{ json: { nextPage: currentPage + 1, row_id: rowId, attempt: attempt + 1, imagesFolderId: $('Build Page URL').last().json.imagesFolderId, documentId: $('Build Page URL').last().json.documentId } }];

return [{ json: {
  current_page: 1,
  row_id: 2,
  images_folder_id: $('Create Images Folder').first().json.id,
  document_id: $('Create spreadsheet').first().json.spreadsheetId
} }];

return [{ json: {
  current_page: 1,
  row_id: 2,
  images_folder_id: $('Create Images Folder').first().json.id,
  document_id: $('Create spreadsheet').first().json.spreadsheetId
} }];

const item = $input.first().json;
const b64 = item.data[0].b64_json;
return [{ json: { imageBase64: b64 } }];

const raw = $input.first().json.output;

let data;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  data = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI Agent вернул невалидный JSON: ' + raw);
}

// Страховочный фильтр: не полагаемся только на то, что модель сама отсеет
// мат/пошлость — она может не распознать бытовой сленг как неприемлемый.
// Если текст содержит что-то из списка — он считается небезопасным на уровне кода,
// даже если модель пометила его как safe.
const BAD_PATTERN = /(хуй|хер\b|пизд|еба(л|н|ть)|ёб|выеб|наеб|подъеб|бля|муда|мудак|сука|дроч|трах|минет|оргазм|секс[а-я]*|гол(ый|ая|ые)\b)/i;

function isEmptyText(text) {
  if (!text) return true;
  const normalized = String(text).trim().toLowerCase();
  return !normalized || normalized === 'null' || normalized === 'undefined' || normalized === 'none';
}

// Трёхступенчатый выбор текста для пузыря:
// 1. dialogueRu, если модель сама сочла его безопасным (и код согласен)
// 2. dialogueMasked — та же реплика с замаскированным матом (п***й)
// 3. dialogueClean — полностью безопасная перефразировка
// Если ни один вариант не прошёл — пузыря не будет вообще (null).
function pickBubbleText(c) {
  if (c.dialogueSafe === true && !isEmptyText(c.dialogueRu) && !BAD_PATTERN.test(c.dialogueRu)) {
    return c.dialogueRu;
  }
  if (!isEmptyText(c.dialogueMasked) && !BAD_PATTERN.test(c.dialogueMasked)) {
    return c.dialogueMasked;
  }
  if (!isEmptyText(c.dialogueClean) && !BAD_PATTERN.test(c.dialogueClean)) {
    return c.dialogueClean;
  }
  return null;
}

const positions = ['on the far left', 'in the middle', 'on the far right', 'at the edge of the frame'];

const charParts = data.characters.map((c, i) => {
  const pos = positions[i] || `in position ${i + 1}`;
  return `${c.descriptionEn}, positioned ${pos}`;
});

const bubbleParts = data.characters
  .map((c, i) => {
    const text = pickBubbleText(c);
    if (!text) return null;
    const pos = positions[i] || `in position ${i + 1}`;
    return `A speech bubble above the character ${pos}, its tail pointing directly down to that exact character's mouth, containing the Russian text "${text}"`;
  })
  .filter(Boolean);

const prompt = [
  'Comic book illustration style, bold black ink outlines, flat cel-shaded colors, exaggerated cartoon expressions. NOT photorealistic, NOT a photo, NOT realistic skin or lighting.',
  data.scene,
  'Characters, left to right: ' + charParts.join('; ') + '.',
  bubbleParts.length
  ? bubbleParts.join('. ') + '.'
  : 'IMPORTANT: absolutely no speech bubbles, no text, no captions, no sound effect lettering, no written words of any kind anywhere in the image — purely visual storytelling only.',
].filter(Boolean).join(' ');

return [{ json: { imagePrompt: prompt, charactersCount: data.characters.length } }];

const hash = $('Try Pick Joke').first().json.hash;
const jokeText = $('Try Pick Joke').first().json.jokeText;

return [{ json: {
  hash,
  joke_excerpt: jokeText.slice(0, 60),
  date_sent: $now.toFormat('yyyy-MM-dd HH:mm'),
  image_url: 'BLOCKED_BY_MODERATION'
} }];
// Note: no separate attempt counter here — Try Pick Joke's own
// MAX_ATTEMPTS (15 pages) is the real safety net against infinite loops.
// This node's only job is to record the blocked joke's hash so the
// dedup check skips it on the next pass through Get Used Hashes.
